function exportModal(kind){const goods=['new','products'].includes(kind),rows=goods?viewRows():visibleTasks(),sel=goods?U.selected.filter(id=>rows.some(x=>x.id===id)):[];openModal('导出清单',`<p class="meta">真实.xlsx文件；ID保留文本。导出不等于执行或完成，不导出共享原始明细。</p><form id="exportForm" data-kind="${goods?'products':'tasks'}"><div class="field"><label>导出范围</label><select name="scope"><option value="filtered">当前筛选全部：${rows.length} 条</option>${goods?`<option value="selected" ${sel.length?'':'disabled'}>已选择商品：${sel.length} 条</option>`:''}</select></div></form><div class="mutedbox">${goods?'指标方案：'+presets[U.preset]+'；'+rangeNote():'任务状态、稳定ID、责任人与生效时间'}<br>只导出Demo中的摘要；不改变任务状态。</div>`,btn('取消','close-modal')+btn('导出 .xlsx','export-confirm','','primary','download'));}
function exportConfirm(){const f=$('#exportForm'),goods=f.dataset.kind==='products',scope=new FormData(f).get('scope');let rows,headers;if(goods){const cols=selectedColumns();let rs=viewRows();if(scope==='selected')rs=rs.filter(r=>U.selected.includes(r.id));headers=['商品ID（文本）','商品名称','平台','Concept','二级类目','新品','当前TOP',...cols.map(k=>colDefs[k][0]),'关联任务','策略','统计开始','统计结束','完整销售日D','库存快照','导出范围','筛选条件','导出时间','数据性质'];const plain=s=>String(s).replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#39;/g,"'").replace(/&quot;/g,'"');rows=rs.map(r=>[r.id,r.product.name,r.product.platform,r.product.concept,r.category,r.isNew?'新品':'非新品',r.rank??'不可排名',...cols.map(k=>plain(colDefs[k][1](r))),S.tasks.filter(t=>t.productId===r.id).map(t=>t.id+' '+stateNames[t.status]).join(' / '),r.policy?.mode||'无例外',U.from,U.to,S.completeThrough,r.product.stockAt,scope==='selected'?'已选商品':'当前筛选全部',JSON.stringify(U.filters.products),new Date().toISOString(),'V9演示；非真实经营数据']);}else{headers=['任务ID（文本）','工作事项','商品ID（文本）','场景','来源','负责人','协作者','核验方式','核验人','执行状态','当前计划开始','当前DDL','原定开始','原定DDL','排期版本','循环规则ID','循环发生日','实际生效','产物版本','记录版本','同步状态','导出时间','数据性质'];rows=visibleTasks().map(t=>[t.id,t.title,t.productId,t.scenario,t.source,user(t.owner).name,(t.collaborators||[]).map(id=>user(id).name).join('、'),t.verificationRequired?'独立核验':'负责人提交完成',t.verifier?user(t.verifier).name:'不需要',stateNames[t.status],t.startAt,t.dueAt,t.originalStartAt,t.originalDueAt,t.scheduleVersion,t.seriesId||'',t.occurrenceDate||'',t.effectiveAt||'',t.artifactVersion,t.version,t.syncStatus,new Date().toISOString(),'V9本机演示；未实际派发']);}if(!rows.length){modalError('当前范围没有记录');return;}download('HM_V9_'+(goods?'商品摘要':'执行清单')+'_'+S.clock+'.xlsx',E.xlsx([headers,...rows],goods?'商品演示摘要':'执行演示清单'),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');closeModal();toast('已导出 '+rows.length+' 条演示摘要；任务状态未变。');}
