function setCorePeriod(kind){U.coreKind=kind;const p=D.period(S,kind,U.from,U.to);U.from=p.start;U.to=p.end;U.selected=[];}
function handleV9Change(el){if(el.id==='v9Platform'){U.platform=el.value;U.filters.products.platform=el.value;render();return true;}if(el.id==='v9Period'){setCorePeriod(el.value);render();return true;}if(['v9From','v9To'].includes(el.id)){const from=$('#v9From').value,to=$('#v9To').value;if(!C.validDate(from)||!C.validDate(to)||from>to||to>S.completeThrough||C.dayDiff(from,to)>90){toast('自选周期需为有效完整日期，最多91天。',true);render();return true;}U.coreKind='custom';U.from=from;U.to=to;render();return true;}if(el.id==='v9Compare'){U.compare=el.value;render();return true;}if(['v9CmpFrom','v9CmpTo'].includes(el.id)){const from=$('#v9CmpFrom').value,to=$('#v9CmpTo').value;if(C.validDate(from)&&C.validDate(to)&&from<=to&&C.dayDiff(from,to)<=90){U.compareFrom=from;U.compareTo=to;}else toast('对比日期无效，最多91天。',true);render();return true;}if(el.id==='v9WorkDate'){if(C.validDate(el.value))U.workDate=el.value;render();return true;}if(el.id==='v9GenerateThrough'){U.generateThrough=el.value;return true;}if(el.id==='v9Relation'){U.taskRelation=el.value;render();return true;}if(el.id==='v9TodoTool'){if(el.value)nav(el.value);return true;}if(['v9TaskKind','v9TaskSkill'].includes(el.id)){const f=$('#newTaskForm'),sk=S.skills.find(x=>x.id===f.elements.skillId.value),hard=['price','ad_budget','purchase'].includes(f.elements.kind.value)||sk?.requiresReview;if(hard)f.elements.verificationRequired.value='true';return true;}return false;}

