document.addEventListener('change',async e=>{const el=e.target;if(handleV9Change(el))return;if(el.id==='presetSelect'){U.preset=el.value;persistUI();render();return;}if(el.id==='newOnly'||el.id==='s4Only'){U.filters.products[el.id==='newOnly'?'newOnly':'s4']=el.checked;U.selected=[];persistUI();render();return;}if(el.id==='rangeStart'||el.id==='rangeEnd'){const start=$('#rangeStart').value,end=$('#rangeEnd').value;if(!C.validDate(start)||!C.validDate(end)||start>end||C.dayDiff(start,end)>90){toast('请选择有效范围，最多91天。',true);render();return;}U.from=start;U.to=end;U.selected=[];persistUI();render();return;}if(el.id==='actorSelect'){actorSwitch(el.value);return;}if(el.matches('[data-filter-view]')){U.filters[el.dataset.filterView]=U.filters[el.dataset.filterView]||{};U.filters[el.dataset.filterView][el.dataset.key]=el.value;U.selected=[];persistUI();render();return;}if(el.id==='includeHistory'){U.filters.new={...U.filters.new,history:el.checked};U.selected=[];render();return;}if(el.dataset.selectProduct){const id=el.dataset.selectProduct;U.selected=el.checked?[...new Set([...U.selected,id])]:U.selected.filter(x=>x!==id);render();return;}if(el.id==='selectAllProducts'){U.selected=el.checked?newProducts().map(p=>p.id):[];render();return;}if(el.id==='evidenceFile'){try{await addFiles(el.files);}catch(err){toast(err.message,true);}return;}if(el.id==='backupFile'){const f=el.files?.[0];if(!f)return;try{if(f.size>8000000)throw Error('备份文件超过本机演示限制。');pendingImport=D.validate(JSON.parse(await f.text()));openModal('确认恢复演示备份',`<p>将用此文件替换当前V9本机存档：</p><div class="kv"><dt>任务</dt><dd>${pendingImport.tasks.length} 项</dd><dt>商品</dt><dd>${pendingImport.products.length} 个</dd><dt>演示业务日</dt><dd>${pendingImport.clock}</dd></div><p class="meta">不会写入飞书，不接受真实经营原始数据。恢复前可先备份当前状态。</p>`,btn('备份当前','backup')+btn('取消','close-modal')+btn('确认恢复','confirm-import','','primary'));}catch(err){toast('备份未导入：'+err.message,true);}finally{el.value='';}return;}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='metricSearch'){clearTimeout(searchTimer);const value=e.target.value;searchTimer=setTimeout(()=>{U.metricSearch=value;render();const x=$('#metricSearch');x?.focus();x?.setSelectionRange(value.length,value.length);},180);return;}if(e.target.closest('#taskForm'))$('#taskForm').dataset.dirty='yes';if(e.target.type==='search'&&e.target.dataset.filterView){clearTimeout(searchTimer);const v=e.target.dataset.filterView,k=e.target.dataset.key,text=e.target.value;searchTimer=setTimeout(()=>{const pos=text.length;U.filters[v]={...U.filters[v],[k]:text};U.selected=[];render();const el=$(`input[data-filter-view="${v}"][data-key="${k}"]`);if(el){el.focus();el.setSelectionRange(pos,pos);}},180);}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='taskForm')$('[data-act="submit-receipt"]')?.click();});
$('#drawerback').addEventListener('click',e=>{if(e.target.id==='drawerback')leaveDrawer();});$('#modalback').addEventListener('click',e=>{if(e.target.id==='modalback')closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modalback').classList.contains('open'))closeModal();else if(U.drawer)leaveDrawer();}if(e.key==='Enter'&&e.target.matches('.card-row[role=button]'))e.target.click();if(e.key==='Tab'){const root=$('#modalback').classList.contains('open')?$('#modal'):U.drawer?$('#drawer'):null;if(!root)return;const nodes=[...root.querySelectorAll('button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')].filter(x=>x.offsetParent!==null);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
